function lineSVG(k,sz){const a=LA[k],sw=sz>=90?2.1:sz>=50?2.4:sz>=34?2.8:3.2;
  return `<svg width="${sz}" height="${sz}" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="${a.d}" ${a.fill?'fill="currentColor" stroke="none"':''}/><g fill="currentColor" stroke="none">${a.f}</g></svg>`}
