// 印章式头像：外圈细印边 + 轻微石刻肌理（#seal 滤镜）
function sealSVG(k,sz){const a=LA[k],sw=sz>=90?2.1:sz>=50?2.4:sz>=34?2.8:3.2,g=66*(a.KK||1),o=(100-g)/2;
  return `<svg width="${sz}" height="${sz}" viewBox="0 0 100 100" style="display:block"><g filter="url(#seal)"><svg x="${o}" y="${o}" width="${g}" height="${g}" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="${a.d}" ${a.fill?'fill="currentColor" stroke="none"':''}/><g fill="currentColor" stroke="none">${a.f}</g></svg></g></svg>`}
